    "Script": "Slideshow = {
    slideIndex: 1,
	init: async function(app, container) {
         app = app || session.app;
         container = container || $(".component[name=Slideshow]");
         var folder = await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq 'Content/Slideshow'&$expand=Files($select=Path)&$select=Files&$top=1");
        var slides = $("[name=slides]",container);
        var images = folder.value[0].Files;
        var i = 0;
        while(i < 5 && i < images.length) {
            var item = images[i];
            var src = session.apiRoot + "DMS/" + item.Path;
            slides.append("<img class = 'slide fade' loading='lazy' src='" + src + "'>");
            if(slides.length > 5) { break; }
            i = i + 1;
        }

        Slideshow.showSlides(Slideshow.slideIndex);
        setTimeout(Slideshow.autoSlide, 5000);
    },

      plusSlides: function(n)   { Slideshow.showSlides(Slideshow.slideIndex += n); },

      showSlides: function(n) {
           var slides = document.getElementsByClassName("slide");
           if (n > slides.length) {Slideshow.slideIndex = 1}
           if (n < 1) {Slideshow.slideIndex = slides.length}
           for (var i = 0; i < slides.length; i++) {
               slides[i].style.display = "none";
           }

           slides[Slideshow.slideIndex-1].style.display = "flex";
      },

      autoSlide: function() { 
         Slideshow.plusSlides(1); 
         setTimeout(Slideshow.autoSlide, 5000);
      }
}",
