    "Script": "DMSFormatting = {
    init: async function (app, container) {
        app = app || session.app;
        DMSFormatting.container = container || $(".component[name=DMSFormatting]");
    },
    
    folderPath: function (folder) {
        return (folder.Path || folder.Name || "")
            .split("/")
            .filter(Boolean)
            .join(" / ");
    },

    fileSize: function (size) {
        if (!size && size !== 0) return "";
        if (size < 1024) return size + " B";
        if (size < 1024 * 1024) return Math.round(size / 1024) + " KB";
        return (size / (1024 * 1024)).toFixed(1) + " MB";
    },

    fileDate: function (value) {
        if (!value) return "";

        var date = new Date(value);

        return isNaN(date.getTime())
            ? ""
            : kendo.toString(date, type.dateFormat);
    },

    extension: function (fileName) {
        if (!fileName || fileName.indexOf(".") === -1) return "default";
        return fileName.split(".").pop().toLowerCase();
    },

    iconPath: function (fileName) {
        return "[api[root]]DMS/Content/DMSIcons/" +
            DMSFormatting.extension(fileName) +
            ".svg";
    }
};",
