    "Content": "",
    "Script": "FileVersionGrid2 = {
    init: async function (app, container, file, readOnly = false) {
        app = app || session.app;
        container = container || $(".component[name=FileVersionGrid2]");

        api.addToMetaCache([
            {
                "Name": "DocumentManagement",
                "Types": [
                    [meta[DocumentManagement/FileContent]],
                ]
            }
        ]);

        var grid = new GridWidget(
            container,
            model.getDatasource({
                endpoint: "DocumentManagement/FileContent",
                odataAppend:
                    "?$select=Id,FileId,Description,Size,CreatedBy,CreatedOn,Version" +
                    "&$filter=FileId eq " +
                    file.Id
            })
        );

        FileVersionGrid2.configureGrid(grid, file, readOnly, container);

        await grid.init();
    },

    configureGrid: function (grid, file, readOnly, container) {
        grid.groupable = false;
        grid.editable = false;
        grid.columns = FileVersionGrid2.getColumns(file);

        if (!readOnly) {
            FileVersionGrid2.addCommands(grid);
        }

        grid.dataBound = function () {
            FileVersionGrid2.bindCommands(grid, file, container);
        };
    },

    addCommands: function (grid) {
        grid.commands.push(
            {
                name: "download",
                icon: "k-i-download",
                text: "[resource_displayname[download]]"
            },
            {
                name: "delete",
                icon: "k-i-trash",
                text: "[resource_displayname[delete]]"
            }
        );
    },

    getColumns: function (file) {
        return [
            {
                field: "Version",
                width: 40,
                title: "#"
            },
            {
                title: "",
                width: 46,
                template: function () {
                    var iconPath = window.DMSFormatting
                        ? DMSFormatting.iconPath(file.Name)
                        : "[api[root]]DMS/Content/DMSIcons/default.svg";

                    return (
                        '<img src="' +
                        iconPath +
                        '" style="height:36px;" onerror="this.src=\'[api[root]]DMS/Content/DMSIcons/default.svg\';" />'
                    );
                }
            },
            {
                title: "[resource_shortdisplayname[name]]",
                template: file.Name
            },
            {
                field: "Size",
                width: 80,
                title: "[resource_shortdisplayname[size]]"
            },
            {
                field: "CreatedBy",
                width: 200,
                title: "[resource_shortdisplayname[createdBy]]"
            },
            {
                field: "CreatedOn",
                width: 200,
                title: "[resource_shortdisplayname[createdOn]]",
                template:
                    "#=kendo.toString(new Date(CreatedOn), '" +
                    type.dateFormat +
                    " HH:mm:ss')#"
            }
        ];
    },

    bindCommands: function (grid, file, container) {
        $("[name=delete]", container)
            .off("click.fileVersionGrid")
            .on("click.fileVersionGrid", async function (event) {
                await FileVersionGrid2.deleteFileVersion(event, grid, file);
            });

        $("[name=download]", container)
            .off("click.fileVersionGrid")
            .on("click.fileVersionGrid", function (event) {
                FileVersionGrid2.downloadFileVersion(event, grid, file);
            });
    },

    downloadFileVersion: function (event, grid, file) {
        event.preventDefault();

        var fileVersion = FileVersionGrid2.getSelectedVersion(event, grid);

        if (!fileVersion) {
            return;
        }

        window.location.assign(
            FileVersionGrid2.getDownloadUrl(file, fileVersion.Version)
        );
    },

    getDownloadUrl: function (file, version) {
        return api.apiRoot +
            "DMS/" +
            file.Path +
            "?version=" +
            encodeURIComponent(version) +
            "&t=" +
            encodeURIComponent(session.token) +
            "&download";
    },

    deleteFileVersion: async function (event, grid, file) {
        event.preventDefault();

        var fileVersion = FileVersionGrid2.getSelectedVersion(event, grid);

        if (!fileVersion) {
            return;
        }

        var confirmDialog = new ConfirmDialog({
            title: "[resource_displayname[areYouSure]]",
            question: "[resource_displayname[doyouwanttodeletethisfileversion]] [resource_displayname[cannotBeUndone]]",
            close: "[resource_displayname[close]]",
            confirm: '<span class="k-icon k-i-check"></span>[resource_displayname[confirm]]'
        });

        confirmDialog.events.confirm = async function () {
            await FileVersionGrid2.deleteFileVersionApiCall(
                grid,
                file,
                fileVersion.Version,
                confirmDialog
            );
        };

        confirmDialog.init();
    },

    getSelectedVersion: function (event, grid) {
        return grid.dataItem(
            $(event.currentTarget).closest("tr")
        );
    },

    deleteFileVersionApiCall: async function (grid, file, version, confirmDialog) {
        try {
            await api.file.destroy(file.Path + "?version=" + version);

            await grid.refresh();
            confirmDialog.events.close();
        } catch (err) {
            error(err);
        }
    }
