            FolderActions.highlightSelectedPath(destinationTree, event.node);
            $("[name=destinationPath]", dialog.element).val(node.folder.Path);
        };

        destinationTree.init();

        if (currentFolderId) {
            setTimeout(function () {
                FolderActions.selectDestinationFolder(
                    destinationTree,
                    currentFolderId,
                    dialog
                );
            }, 0);
        }

        $('<button type="button" class="btn btn-sm btn-primary float-end mt-2" name="move">' +
            "[resource_displayname[move]]" +
        "</button>")
            .appendTo(dialog.element)
            .off("click.folderActions")
            .on("click.folderActions", async function (event) {
                event.preventDefault();
                await FolderActions.moveFiles(dialog, files, onComplete);
            });
