    "Script": "FolderManagement2 = {
        init: async function (app, container, folder, readOnly, disablePaging = false) {
        app = app || session.app;
        container = container || $(".component[name=FolderManagement2]");
        readOnly = readOnly || false;

        if (!folder) {
            return;
        }

        api.addToMetaCache([{
            Name: "DocumentManagement",
            Types: [
                [meta[DocumentManagement/Folder]],
                [meta[DocumentManagement/File]],
                [meta[DocumentManagement/FileContent]]
            ]
        }]);

        var shell = FolderManagement2.renderShell(container);
        var fileList = $("[name=fileList]", shell);

        if (!fileList.length) {
            console.error("FolderManagement2 fileList container was not rendered.");
            return;
        }

        await FolderManagement2.bindBreadcrumbNavigation(shell, app, folder, readOnly, disablePaging);

        var actions = await FolderManagement2.loadActionComponents(shell, app);

        FolderManagement2.bindToolbarActions(shell, app, folder, readOnly, disablePaging, actions.upload);
        FolderManagement2.bindDesktopUploadDrop(shell, app, folder, readOnly, disablePaging, actions.upload);

        await FolderManagement2.buildWidget(fileList, folder, readOnly, app, disablePaging);
    },

    renderShell: function (container) {
        var shell = $("[name=folderManagementShell]", container);

        if (!shell.length) {
            shell = $('<div name="folderManagementShell"></div>').appendTo(container);
        }

        shell.html([
            '<div class="folder-management">',
                '<div class="folder-main-toolbar">',
                    '<div class="folder-title-row">',
                        '<div class="folder-breadcrumb" name="folderPath"></div>',
