                editable: false,
                template:
                    "#: Contents && Contents.length ? kendo.toString(new Date(Contents[0].CreatedOn), '" +
                    type.dateFormat +
                    " HH:mm:ss') : '' #",
                width: "[theme[columns.medium]]"
            }
        ];
    },

    bindGridSelection: function (grid, selectionKeys) {
        grid.gridElement
            .off("click.fileSelection", "tr.k-master-row")
            .on("click.fileSelection", "tr.k-master-row", function (event) {
                if (selectionKeys.shift) {
                    FolderManagement2.shiftClick(event, grid);
                }

                if (selectionKeys.ctrl) {
                    FolderManagement2.ctrlClick(event, grid);
                }
            });
    },

    bindGridEvents: function (grid, readOnly) {
        grid.gridElement
            .off("contextmenu.fileActions")
            .on("contextmenu.fileActions", "tr.k-master-row", function (event) {
                event.preventDefault();
            })
            .off("click.contextToolbar")
            .on("click.contextToolbar", "tr.k-master-row, input[type=checkbox]", function () {
                setTimeout(function () {
                    FolderManagement2.updateContextToolbar(grid);
                }, 0);
            });
    },

    bindContextToolbar: function (grid) {
        var toolbar = grid.gridElement
            .closest(".folder-management")
            .find("[name=contextToolbar]");

        $("[name=contextMove]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", async function (event) {
                event.preventDefault();

                await FolderManagement2.loadFolderActions(
                    grid.gridElement.closest(".folder-management"),
                    grid.app,
                    function (actions) {
                        actions.openMove(grid, function () {
                            return FolderManagement2.afterFileAction(grid);
                        });
                    }
                );
            });

        $("[name=contextDownload]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", function (event) {
                FileActions.downloadSelected(event, grid);
            });

        $("[name=contextDelete]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", function (event) {
                FileActions.deleteSelected(event, grid, function () {
                    return FolderManagement2.afterFileAction(grid);
                });
            });
    },

    afterFileAction: async function (grid) {
        await grid.refresh();
        FolderManagement2.updateContextToolbar(grid);
    },

    updateContextToolbar: function (grid) {
        var count = grid.select().length;
        var toolbar = grid.gridElement
            .closest(".folder-management")
            .find("[name=contextToolbar]");

        if (!toolbar.length) {
            return;
        }

        toolbar.toggleClass("context-toolbar-hidden", count === 0);

        if (count) {
            $("[name=selectedCount]", toolbar).text(
                count +
                " " +
                (count === 1 ? "item" : "items") +
                " selected"
            );
        }

        FolderManagement2.resizeGrid(grid);
    },

    bindFileSearch: function (grid) {
        grid.gridElement
            .closest(".folder-management")
            .find("[name=fileSearch]")
            .off("input.fileSearch")
            .on(
                "input.fileSearch",
                FolderManagement2.debounce(function () {
                    FolderManagement2.searchFiles(grid, $(this).val());
                }, 250)
            );
    },

    searchFiles: function (grid, searchTerm) {
        var value = (searchTerm || "").trim();

        grid.kendoObject.dataSource.filter(
            value
                ? {
                    logic: "or",
                    filters: [
                        {
                            field: "Name",
                            operator: "contains",
                            value: value,
                            ignoreCase: true
                        },
                        {
                            field: "CreatedBy",
                            operator: "contains",
                            value: value,
                            ignoreCase: true
                        }
                    ]
                }
                : {}
        );
    },

    clearSelection: function (event, grid) {
        event.preventDefault();

        grid.clearSelection();
        FolderManagement2.updateContextToolbar(grid);
    },

    ctrlClick: function (event, grid) {
        grid.kendoObject.select($(event.currentTarget).closest("tr"));
        FolderManagement2.updateContextToolbar(grid);
    },

    shiftClick: function (event, grid) {
        var selectedRows = $("tr.k-state-selected", grid.gridElement);

        if (!selectedRows.length) {
            return;
        }

        var selectedIndex = selectedRows.index();
        var currentIndex = $(event.currentTarget).closest("tr").index();
        var children = selectedRows.parent().children();
        var start = Math.min(selectedIndex, currentIndex);
        var end = Math.max(selectedIndex, currentIndex);

        grid.kendoObject.clearSelection();

        for (var i = start; i <= end; i++) {
            grid.kendoObject.select(children[i]);
        }

        FolderManagement2.updateContextToolbar(grid);
    },

    resizeGrid: function (grid) {
        setTimeout(function () {
            if (grid.kendoObject && grid.kendoObject.resize) {
                grid.kendoObject.resize();
            }
        }, 0);
    },

    debounce: function (callback, delay) {
        var timer;

        return function () {
            var context = this;
            var args = arguments;

            clearTimeout(timer);

            timer = setTimeout(function () {
                callback.apply(context, args);
            }, delay);
        };
    },

    bindDesktopUploadDrop: function (shell, app, folder, readOnly, disablePaging, uploadActions) {
        shell
            .off("dragenter.folderUpload dragover.folderUpload dragleave.folderUpload drop.folderUpload")
            .on("dragenter.folderUpload dragover.folderUpload", function (event) {
                if (!FolderManagement2.isDesktopFileDrop(event.originalEvent)) {
                    return;
                }

                event.preventDefault();
                event.stopPropagation();

                event.originalEvent.dataTransfer.dropEffect = "copy";
                shell.find(".folder-management").addClass("folder-upload-drag-active");
            })
            .on("dragleave.folderUpload", function (event) {
                if ($(event.relatedTarget).closest(shell).length) {
                    return;
                }

                shell.find(".folder-management").removeClass("folder-upload-drag-active");
            })
            .on("drop.folderUpload", async function (event) {
                if (!FolderManagement2.isDesktopFileDrop(event.originalEvent)) {
                    return;
                }

                event.preventDefault();
                event.stopPropagation();

                shell.find(".folder-management").removeClass("folder-upload-drag-active");

                if (!uploadActions || !uploadActions.getDroppedUploadItems) {
                    console.error("UploadActions was not loaded for upload drop.");
                    return;
                }

                var uploadItems = await uploadActions.getDroppedUploadItems(event.originalEvent);

                if (!uploadItems.length) {
                    return;
                }

                uploadActions.openUniversalUpload(
                    folder,
                    function (createdFolder) {
                        return FolderManagement2.afterUploadComplete(app, folder, readOnly, disablePaging, createdFolder);
                    },
                    uploadItems
                );
            });
    },

    isDesktopFileDrop: function (event) {
        return !!(
            event &&
            event.dataTransfer &&
            event.dataTransfer.types &&
            Array.prototype.indexOf.call(event.dataTransfer.types, "Files") >= 0
        );
    },

    bindFileDrag: function (grid) {
        grid.gridElement
            .find("tr.k-master-row")
            .attr("draggable", true);

        grid.gridElement
            .off("dragstart.fileMove dragend.fileMove", "tr.k-master-row")
            .on("dragstart.fileMove", "tr.k-master-row", function (event) {
                var row = $(this);
                var draggedFile = grid.dataItem
                    ? grid.dataItem(row)
                    : grid.kendoObject.dataItem(row);

                var selectedFiles = FolderManagement2.rowIsSelected(row)
                    ? grid.select()
                    : [draggedFile];

                selectedFiles = selectedFiles.filter(function (file) {
                    return !!file;
                });

                if (!selectedFiles.length) {
                    return FolderManagement2.cancelDrag(event);
                }

                event.originalEvent.dataTransfer.effectAllowed = "move";
                event.originalEvent.dataTransfer.setData(
                    "application/x-dms-files",
                    JSON.stringify({
                        files: selectedFiles.map(function (file) {
                            return {
                                Id: file.Id,
                                Name: file.Name,
                                Path: file.Path,
                                FolderId: file.FolderId
                            };
                        })
                    })
                );

                event.originalEvent.dataTransfer.setData(
                    "text/plain",
                    selectedFiles.length +
                        " " +
                        (selectedFiles.length === 1 ? "file" : "files")
                );

                grid.gridElement.addClass("dms-file-dragging");
            })
            .on("dragend.fileMove", "tr.k-master-row", function () {
                grid.gridElement.removeClass("dms-file-dragging");
            });
    },

    rowIsSelected: function (row) {
        return row.hasClass("k-selected") ||
            row.hasClass("k-state-selected");
    },

    cancelDrag: function (event) {
        event.preventDefault();
        event.stopPropagation();

        if (event.originalEvent && event.originalEvent.dataTransfer) {
            event.originalEvent.dataTransfer.effectAllowed = "none";
        }

        return false;
    },

    reloadFolderView: async function (app, folder, readOnly, disablePaging) {
        if (!folder) {
            return;
        }

        var container = $(".component[name=FolderManagement2]");
        var shell = $("[name=folderManagementShell]", container);
        var fileList = $("[name=fileList]", shell);

        if (!shell.length || !fileList.length) {
            return FolderManagement2.init(app, container, folder, readOnly, disablePaging);
        }

        await FolderManagement2.bindBreadcrumbNavigation(shell, app, folder, readOnly, disablePaging);

        var actions = await FolderManagement2.loadActionComponents(shell, app);

        FolderManagement2.bindToolbarActions(shell, app, folder, readOnly, disablePaging, actions.upload);
        FolderManagement2.bindDesktopUploadDrop(shell, app, folder, readOnly, disablePaging, actions.upload);

        fileList.empty();

        await FolderManagement2.buildWidget(fileList, folder, readOnly, app, disablePaging);
    },

    afterUploadComplete: async function (app, currentFolder, readOnly, disablePaging, createdFolder) {
        var folderToLoad = currentFolder;

        if (createdFolder && createdFolder.Path) {
            var matchedFolder = await FolderManagement2.getFolderByPath(app, createdFolder.Path);

            if (matchedFolder) {
                folderToLoad = matchedFolder;
            }
        }

        await DocumentManagement.refreshTreeAfterFolderChange(app, folderToLoad.Id);

        await FolderManagement2.reloadFolderView(app, folderToLoad, readOnly, disablePaging);

        FolderManagement2.selectFolderInTree(folderToLoad);
    },

    afterFolderCreate: async function (app, currentFolder, readOnly, disablePaging, createdFolder) {
        var folderToLoad = createdFolder || currentFolder;

        if (folderToLoad && folderToLoad.Path) {
            var matchedFolder = await FolderManagement2.getFolderByPath(app, folderToLoad.Path);

            if (matchedFolder) {
                folderToLoad = matchedFolder;
            }
        }

        await DocumentManagement.refreshTreeAfterFolderChange(app, folderToLoad.Id);

        await FolderManagement2.reloadFolderView(app, folderToLoad, readOnly, disablePaging);

        FolderManagement2.selectFolderInTree(folderToLoad);
    },

    afterFolderManage: async function (app, folder, readOnly, disablePaging) {
        var latestFolder = await api.get("DocumentManagement/Folder(" + folder.Id + ")");

        await DocumentManagement.refreshTreeAfterFolderChange(app, latestFolder.Id);

        await FolderManagement2.reloadFolderView(app, latestFolder, readOnly, disablePaging);

        FolderManagement2.selectFolderInTree(latestFolder);
    },

    getFolderByPath: async function (app, path) {
        var result = await api.get(
            "DocumentManagement/Folder?$filter=AppId eq " +
            app.Id +
            " and Path eq '" +
            path.replace(/'/g, "''") +
            "'&_=" +
            Date.now()
        );

        return result && result.value && result.value.length
            ? result.value[0]
            : null;
    },
};",
